package io.ecosync.restcontract;
import java.nio.file.*;
import java.util.*;
import org.junit.jupiter.api.Test;
import static org.assertj.core.api.Assertions.*;
import static io.ecosync.restcontract.RestJson.*;
class OpenApiImporterTest {
 @Test void assertionKeywordsCannotBeSilentlyAppliedToWrongTypes(){for(var schema:List.of(Map.of("type","integer","minLength",2),Map.of("type","string","minimum",2),Map.of("type","boolean","maxItems",2),Map.of("type","string","nullable",true,"enum",List.of("x"))))assertThatThrownBy(()->RestSchema.normalize(new HashMap<String,Object>(schema),false)).isInstanceOf(RestFailure.class);}
 static String document(){return """
 {"openapi":"3.1.0","info":{"title":"Independent","version":"2"},"paths":{"/people/{id}":{"get":{"operationId":"person","parameters":[{"name":"id","in":"path","required":true,"schema":{"type":"integer","minimum":1}}],"responses":{"200":{"description":"one","content":{"application/json":{"schema":{"$ref":"#/components/schemas/Person"}}}}}}}},"components":{"schemas":{"Person":{"type":"object","properties":{"name":{"type":"string"}},"required":["name"],"additionalProperties":false}}}}
 """;}
 @Test void importsBothVersionsAndRealSupplierWithoutGrantingAnything()throws Exception{for(String version:List.of("3.0.3","3.1.0")){var c=new OpenApiImporter().parse(document().replace("3.1.0",version));assertThat(c.operations()).hasSize(1);assertThat(c.operations().getFirst().supported()).isTrue();}var source=Path.of("../demo-systems/supplier-api/openapi.json");var c=new OpenApiImporter().parse(Files.readString(source));assertThat(c.operations()).hasSize(7).allMatch(OpenApiImporter.Operation::supported);}
 @Test void malformedDuplicateAndTrailingJsonAreDenied(){for(String bad:List.of("{",document()+"{}",document().replace("\"openapi\":","\"openapi\":\"3.0.3\",\"openapi\":")))assertThatThrownBy(()->new OpenApiImporter().parse(bad)).isInstanceOf(RestFailure.class);}
 @Test void remoteRelativeUnresolvedAndCircularRefsFailBeforeReview(){for(String ref:List.of("https://evil/schema","file:///tmp/x","../schema.json","#/missing","#/components/schemas/Person")){String value=document().replace("\"type\":\"object\",\"properties\":{\"name\":{\"type\":\"string\"}},\"required\":[\"name\"],\"additionalProperties\":false","\"$ref\":\""+ref+"\"");assertThatThrownBy(()->new OpenApiImporter().parse(value)).isInstanceOf(RestFailure.class);}}
 @Test void writesBodiesHostsAndXmlAreVisibleButUnsupported(){for(String value:List.of(document().replace("\"get\":","\"post\":"),document().replace("\"operationId\":","\"requestBody\":{},\"operationId\":"),document().replace("\"operationId\":","\"servers\":[{\"url\":\"https://evil\"}],\"operationId\":"),document().replace("application/json","application/xml"))){var op=new OpenApiImporter().parse(value).operations().getFirst();assertThat(op.supported()).isFalse();assertThat(op.reason()).startsWith("REST_");}}
 @Test void unknownSchemaAssertionsAndParameterSerializationNeverBroaden(){for(String value:List.of(document().replace("\"type\":\"integer\"","\"type\":\"integer\",\"multipleOf\":2"),document().replace("\"in\":\"path\"","\"in\":\"header\""),document().replace("\"in\":\"path\"","\"in\":\"path\",\"style\":\"matrix\""))){assertThat(new OpenApiImporter().parse(value).operations().getFirst().supported()).isFalse();}}
 @Test void idsAndPathsCannotCollide(){String value=document().replace("\"/people/{id}\":", "\"/other/{id}\":{\"get\":{\"operationId\":\"person\"}},\"/people/{id}\":");assertThatThrownBy(()->new OpenApiImporter().parse(value)).isInstanceOf(RestFailure.class);}
 @Test void configurableDocumentPathOperationAndExpansionBounds(){assertThatThrownBy(()->new OpenApiImporter(new OpenApiImporter.Limits(128,1,1,1)).parse(document())).isInstanceOf(RestFailure.class);assertThatThrownBy(()->new OpenApiImporter(new OpenApiImporter.Limits(262144,1,1,10)).parse(document())).isInstanceOf(RestFailure.class);String many=document().replace("\"get\":", "\"post\":{},\"get\":");assertThatThrownBy(()->new OpenApiImporter(new OpenApiImporter.Limits(262144,1,1,20000)).parse(many)).isInstanceOf(RestFailure.class);}
 @Test void fingerprintsIgnoreFormattingButBindContractChanges(){var p=new OpenApiImporter();assertThat(p.parse(document()).fingerprint()).isEqualTo(p.parse(document().replace(":",": ")).fingerprint());assertThat(p.parse(document()).fingerprint()).isNotEqualTo(p.parse(document().replace("\"minimum\":1","\"minimum\":2")).fingerprint());}
 @Test void typedArgumentsAreEncodedAndUnexpectedValuesFail(){var op=MAPPER.convertValue(new OpenApiImporter().parse(document()).operations().getFirst(),Map.class);assertThat(RestArguments.target(op,Map.of("id",2))).isEqualTo("/people/2");for(var args:List.of(Map.of("id","2"),Map.of("id",0),Map.of("id",2,"url","http://evil"),Map.of("id",2,"Host","evil")))assertThatThrownBy(()->RestArguments.target(op,new HashMap<String,Object>(args))).isInstanceOf(RestFailure.class);}
 @Test void boundedPatternSubsetAndSchemaOutputValidation(){assertThat(RestSchema.safePattern("^(a+)+$")).isFalse();var s=RestSchema.normalize(Map.of("type","object","properties",Map.of("n",Map.of("type","integer")),"required",List.of("n"),"additionalProperties",false),true);RestSchema.validate(s,Map.of("n",1),"REST_INVALID_RESPONSE");assertThatThrownBy(()->RestSchema.validate(s,Map.of("n","1"),"REST_INVALID_RESPONSE")).isInstanceOf(RestFailure.class);}
}
